using NUnit.Framework;

[TestFixture]
public class CountCaseTests
{
    [Test]
    public void Counts_Upper_And_Lower_Correctly()
    {
        var result = CountCase("AnNa123!");
        Assert.That(result.upper, Is.EqualTo(2));
        Assert.That(result.lower, Is.EqualTo(2));
    }

    private (int upper, int lower) CountCase(string text)
    {
        int upper = 0;
        int lower = 0;

        foreach (var ch in text)
        {
            if (char.IsUpper(ch))
                upper++;
            else if (char.IsLower(ch))
                lower++;
        }

        return (upper, lower);
    }
}
